using System.Diagnostics;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using RAWSelectionAssistant.Core.Models;
using RAWSelectionAssistant.Core.Services.AssetLibrary;
var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var path=Path.Combine(root,"synthetic-10128.db");if(File.Exists(path))throw new IOException("Fresh fixture required");await using var repo=new SqliteAssetLibraryRepository(path);await repo.InitializeAsync();await using var c=new SqliteConnection("Data Source="+path);await c.OpenAsync();
var now=new DateTimeOffset(2026,9,2,0,0,0,TimeSpan.Zero);var ids=new List<Guid>();await using(var tx=(SqliteTransaction)await c.BeginTransactionAsync())for(var i=0;i<10128;i++){var id=Guid.NewGuid();ids.Add(id);await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO AssetItems(AssetId,SourcePath,NormalizedSourcePath,DuplicateDiscriminator,DisplayName,Extension,MediaType,FileSize,Width,Height,Orientation,AddedAt,ModifiedAt,Rating,Comment,IsMissing,IsArchived,ImportMode) VALUES($id,$path,$path,'',$name,'.jpg','Image',1024,1600,1000,'Landscape',$added,$added,$rating,'batch',0,$archived,'Reference');";cmd.Parameters.AddWithValue("$id",id.ToString("D"));cmd.Parameters.AddWithValue("$path","synthetic://company/"+id);cmd.Parameters.AddWithValue("$name",$"synthetic-{i:00000}");cmd.Parameters.AddWithValue("$added",now.AddSeconds(-i).ToString("O"));cmd.Parameters.AddWithValue("$rating",i%6);cmd.Parameters.AddWithValue("$archived",i>=10000?1:0);await cmd.ExecuteNonQueryAsync();if(i==10127)await tx.CommitAsync();}
var folder=await repo.SaveFolderAsync(new(Guid.NewGuid(),null,"scope"));await repo.AddToFolderAsync(ids.Take(100).ToArray(),folder.FolderId);var document=new AssetQueryDocument{RootGroup=AssetQueryNode.Group(AssetQueryLogic.All,[AssetQueryNode.Rule(AssetQueryField.Rating,AssetQueryOperator.GreaterThanOrEqual,["3"])])};var current=new AssetLibraryQuery(FolderId:folder.FolderId,PageSize:100){Document=document};var all=current with{Document=document with{Scope=AssetQueryScope.AllAssets}};var samples=new List<object>();var traces=new List<AssetLibraryQueryDiagnostics.Query>();using var capture=AssetLibraryQueryDiagnostics.Capture(traces.Add);
for(var cycle=0;cycle<4;cycle++)foreach(var (label,query) in new[]{("current",current),("all",all)}){var watch=Stopwatch.StartNew();var result=await repo.QueryAsync(query);watch.Stop();if(label=="all"&&result.TotalCount!=4999)throw new InvalidDataException("scope count regression");samples.Add(new{cycle,cache=cycle==0?"cold-process first query (OS cache not purged)":"warm",label,ms=watch.Elapsed.TotalMilliseconds,result.TotalCount,ids=result.Items.Select(x=>x.AssetId),first=result.Items.FirstOrDefault()?.DisplayName,last=result.Items.LastOrDefault()?.DisplayName});}
var plans=new List<object>();foreach(var trace in traces){var phase=new List<object>();foreach(var (sql,parameters) in new[]{(trace.CountSql,trace.CountParameters),(trace.PageSql,trace.PageParameters)}){await using var cmd=c.CreateCommand();cmd.CommandText="EXPLAIN QUERY PLAN "+sql;foreach(var p in parameters)cmd.Parameters.AddWithValue(p.Key,p.Value??DBNull.Value);var rows=new List<string>();await using var r=await cmd.ExecuteReaderAsync();while(await r.ReadAsync())rows.Add(r.GetString(3));phase.Add(new{sql,parameters,rows});}plans.Add(new{trace,phase});}
var settings=new Dictionary<string,object?>();foreach(var n in new[]{"journal_mode","synchronous","cache_size","page_size"}){await using var cmd=c.CreateCommand();cmd.CommandText="PRAGMA "+n;settings[n]=await cmd.ExecuteScalarAsync();}var drive=new DriveInfo(Path.GetPathRoot(path)!);await File.WriteAllTextAsync(Path.Combine(root,"measurements.json"),JsonSerializer.Serialize(new{path,count=10128,visible=10000,coldWarm=samples,plans,sqlite=c.ServerVersion,settings,drive.AvailableFreeSpace,drive.DriveFormat,uiDispatch="NOT_MEASURED: this executable measures actual repository, not WPF scheduling",OSCacheFlush=false,thresholdMs=400},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(Path.Combine(root,"measurements.json"));
